from transformers import pipeline
from torch import nn, cuda
import torch.distributed as dist
from torch.nn.parallel import DistributedDataParallel
import torch.multiprocessing as mp

# Ensure the script can handle multiple GPUs
if cuda.is_available():    
    num_gpus = cuda.device_count()
    device = 'cuda' if num_gpus > 0 else 'cpu'
else:
    device = 'cpu'

class Gpt3Translator(nn.Module):
    def __init__(self):
        super(Gpt3Translator, self).__init__()
        self.model = pipeline('translation_en_to_fr', model='t5-base', device=0)

    def forward(self, text):
        try:
            if isinstance(text, str):
                return self.model(text)
            else:
                raise TypeError("Expected String as input") 
        except Exception as e:
            print("An error occured:", str(e))

def run(rank, size, text_to_translate):
    torch.manual_seed(1234)
    model = Gpt3Translator()
    ddp_model = DistributedDataParallel(model)

    output = ddp_model(text_to_translate)
    print(f'Output {rank}: {output}')


def init_processes(rank, size, text_to_translate, fn, backend='gloo'):
